    },
      desc_cat: "muestra un archivo",
      desc_tree: "muestra el árbol de directorios",
      desc_open: "abre un enlace o archivo, o entra en un directorio",
      desc_theme: "muestra o cambia el tema",
      desc_lang: "muestra o cambia el idioma",
