      infoRole: "Desarrollador full-stack",
      infoFocus: "Aplicaciones web · Ciberseguridad",
      infoLocation: "Madrid, España",
      infoUptime: "{minutes} min",
      desc_scan: "ejecuta un escaneo de vulnerabilidades simulado",
